CREATE PROCEDURE [OrderTests].[test that ApplyDiscounts gives 10% to VIP customers]
AS
BEGIN
    -- Arrange
    EXEC tSQLt.FakeTable @TableName = 'dbo.Customers';
    EXEC tSQLt.FakeTable @TableName = 'dbo.Orders';

    INSERT INTO dbo.Customers (CustomerID, IsVIP) VALUES (1, 1);
    INSERT INTO dbo.Orders (OrderID, CustomerID, TotalAmount) VALUES (10, 1, 100.00);

    -- Act
    EXEC dbo.ApplyDiscounts @OrderID = 10;

    -- Assert
    DECLARE @ActualTotal DECIMAL(18,2) = (SELECT TotalAmount FROM dbo.Orders WHERE OrderID = 10);
    EXEC tSQLt.AssertEquals @Expected = 90.00, @Actual = @ActualTotal;
END;

